<script setup>import SeoHead from '@/Components/Public/SeoHead.vue'; import PublicLayout from '@/Layouts/PublicLayout.vue'; import InputError from '@/Components/InputError.vue'; import { useForm } from '@inertiajs/vue3'; const form=useForm({name:'',email:'',phone:'',company:'',subject:'',message:''}); const submit=()=>form.post(route('contact.store'),{preserveScroll:true,onSuccess:()=>form.reset()});</script>
<template><SeoHead title="Contact KernelBridge Technologies" description="Contact KernelBridge Technologies LTD about software products, custom development or digital transformation." canonical="https://kernelbridge.com/contact"/><PublicLayout><section class="page-hero"><div class="page-shell"><p class="section-label !text-teal-300">Contact us</p><h1 class="page-title">Let’s talk about what you want to improve.</h1><p class="page-intro">Share your challenge, goal or question. Our team will respond with a clear next step.</p></div></section><section class="page-shell grid gap-12 py-20 lg:grid-cols-[.8fr_1.2fr]"><div><h2 class="section-title">Start a conversation</h2><p class="section-copy">For product, partnership and service enquiries, complete the form or email hello@kernelbridge.com.</p><div class="mt-8 rounded-2xl bg-[#0B3D6E] p-6 text-white"><p class="font-bold">KernelBridge Technologies LTD</p><p class="mt-2 text-sm text-blue-100">Professional software platforms and digital transformation services.</p></div></div><form class="form-card" @submit.prevent="submit"><div v-if="$page.props.flash.success" role="status" class="success-message">{{ $page.props.flash.success }}</div><div class="form-grid"><label>Name<input v-model="form.name" required autocomplete="name"/><InputError :message="form.errors.name"/></label><label>Email<input v-model="form.email" required type="email" autocomplete="email"/><InputError :message="form.errors.email"/></label><label>Phone<input v-model="form.phone" type="tel" autocomplete="tel"/><InputError :message="form.errors.phone"/></label><label>Company<input v-model="form.company" autocomplete="organization"/><InputError :message="form.errors.company"/></label></div><label>Subject<input v-model="form.subject" required/><InputError :message="form.errors.subject"/></label><label>Message<textarea v-model="form.message" required rows="6"></textarea><InputError :message="form.errors.message"/></label><button class="form-button" :disabled="form.processing">{{ form.processing ? 'Sending…' : 'Send message' }}</button></form></section></PublicLayout></template>
